76	  /**
77	   * Writes the specified container merkle tree to the specified container's checksum file.
78	   * The data merkle tree within the file is replaced with the {@code tree} parameter, but all other content of the
79	   * file remains unchanged.
80	   * Concurrent writes to the same file are coordinated internally.
81	   */
82	  public void writeContainerDataTree(ContainerData data, ContainerMerkleTree tree) throws IOException {
83	    long containerID = data.getContainerID();
84	    Lock writeLock = getLock(containerID);
85	    writeLock.lock();
86	    try {
87	      ContainerProtos.ContainerChecksumInfo.Builder checksumInfoBuilder = null;
88	      try {
89	        // If the file is not present, we will create the data for the first time. This happens under a write lock.
90	        checksumInfoBuilder = read(data)
91	            .orElse(ContainerProtos.ContainerChecksumInfo.newBuilder());
92	      } catch (IOException ex) {
93	        LOG.error("Failed to read container checksum tree file for container {}. Overwriting it with a new instance.",
94	            containerID, ex);
95	        checksumInfoBuilder = ContainerProtos.ContainerChecksumInfo.newBuilder();
96	      }
97	
98	      checksumInfoBuilder
99	          .setContainerID(containerID)
100	          .setContainerMerkleTree(captureLatencyNs(metrics.getCreateMerkleTreeLatencyNS(), tree::toProto));
101	      write(data, checksumInfoBuilder.build());
102	      LOG.debug("Data merkle tree for container {} updated", containerID);
103	    } finally {
104	      writeLock.unlock();
105	    }
106	  }
107	
108	  /**
109	   * Adds the specified blocks to the list of deleted blocks specified in the container's checksum file.
110	   * All other content of the file remains unchanged.
111	   * Concurrent writes to the same file are coordinated internally.
112	   */
113	  public void markBlocksAsDeleted(KeyValueContainerData data, Collection<Long> deletedBlockIDs) throws IOException {
114	    long containerID = data.getContainerID();
115	    Lock writeLock = getLock(containerID);
116	    writeLock.lock();
117	    try {
118	      ContainerProtos.ContainerChecksumInfo.Builder checksumInfoBuilder = null;
119	      try {
120	        // If the file is not present, we will create the data for the first time. This happens under a write lock.
121	        checksumInfoBuilder = read(data)
122	            .orElse(ContainerProtos.ContainerChecksumInfo.newBuilder());
123	      } catch (IOException ex) {
124	        LOG.error("Failed to read container checksum tree file for container {}. Overwriting it with a new instance.",
125	            data.getContainerID(), ex);
126	        checksumInfoBuilder = ContainerProtos.ContainerChecksumInfo.newBuilder();
127	      }
128	
129	      // Although the persisted block list should already be sorted, we will sort it here to make sure.
130	      // This will automatically fix any bugs in the persisted order that may show up.
131	      SortedSet<Long> sortedDeletedBlockIDs = new TreeSet<>(checksumInfoBuilder.getDeletedBlocksList());
132	      sortedDeletedBlockIDs.addAll(deletedBlockIDs);
133	
134	      checksumInfoBuilder
135	          .setContainerID(containerID)
136	          .clearDeletedBlocks()
137	          .addAllDeletedBlocks(sortedDeletedBlockIDs);
138	      write(data, checksumInfoBuilder.build());
139	      LOG.debug("Deleted block list for container {} updated with {} new blocks", data.getContainerID(),
140	          sortedDeletedBlockIDs.size());
141	    } finally {
142	      writeLock.unlock();
143	    }
144	  }
